def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([-5]), fmt([3, 3, 3, 3]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1]),
             fmt([10**9, -10**9]), fmt([2, 1])]
    for n in (2, 3, 4, 6, 9, 15, 25, 40):
        for _ in range(2):
            tests.append(fmt([rng.randint(-20, 20) for _ in range(n)]))
    N = 10**5
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt(sorted(rng.randint(-10**9, 10**9) for _ in range(N))))
    tests.append(fmt(sorted((rng.randint(-10**9, 10**9) for _ in range(N)), reverse=True)))
    tests.append(fmt([rng.randint(0, 5) for _ in range(N)]))
    return tests
